// SPDX-License-Identifier: MIT
// Glimmerloom Ledger (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/glimmerloom.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "glimmerloom:<seed>:<difficulty>"), so the same seed is the same market as the Python game.
// All market math is integer; the only float is random() against the rumor truth rate (bit-exact).
// Byte parity goes through engines/unreal/core-test/glimmerloom_parity.txt (glimmerloom_core_test.cpp), generated by
// tools/minigames/glimmerloom_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <numeric>
#include <string>
#include <vector>

namespace daedalus { namespace glimmerloom {

inline const char* GameId() { return "glimmerloom"; }
inline const char* Title() { return "Glimmerloom Ledger"; }

struct Difficulty { const char* Name; int Hues; int Days; int Purse; int Target; int Satchel; double Truth; int Tax; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = {
		{ "easy", 3, 12, 100, 130, 20, 0.85, 0 },
		{ "normal", 4, 10, 100, 135, 15, 0.75, 0 },
		{ "hard", 5, 8, 100, 110, 12, 0.7, 1 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

inline const char* HueName(int I) { static const char* Names[] = { "ember", "tide", "verdant", "gale", "umbra" }; return Names[I]; }
constexpr int Low = 3, High = 20;
constexpr int MoveSteps[7] = { -3, -2, -1, 0, 1, 2, 3 };

enum class Kind : int { Buy = 0, Sell, Rest };
struct Action { Kind K = Kind::Rest; int Hue = 0; int Count = 0; };

struct Game
{
	const Difficulty* Diff = nullptr;
	int Day = 1, Purse = 0;
	std::vector<int> Prices, Satchel, Moves;
	int RumorHue = 0; bool RumorRise = false;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, BadPick, NoRoom, NotHeld, GameOver };

	/** PrismGame.start + Game.setup. False on an unknown difficulty. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		Day = 1; Purse = Diff->Purse;
		Prices.assign(static_cast<size_t>(Diff->Hues), 0);
		for (int& P : Prices) P = 6 + static_cast<int>(Rng.RandRange(9));  // randint(6, 14)
		Satchel.assign(Prices.size(), 0);
		NextMoves();
		return true;
	}

	/** Roll tomorrow's price moves, then the rumor about one of them (Game._next_moves). */
	void NextMoves()
	{
		Moves.assign(Prices.size(), 0);
		for (int& M : Moves) M = MoveSteps[Rng.ChoiceIndex(7)];
		RumorHue = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(Prices.size())));
		RumorRise = Moves[static_cast<size_t>(RumorHue)] > 0;
		if (Rng.RandomDouble() >= Diff->Truth) RumorRise = !RumorRise;
	}

	int Held() const { return std::accumulate(Satchel.begin(), Satchel.end(), 0); }
	int Sale(int Hue, int Count) const { return Count * std::max(0, Prices[static_cast<size_t>(Hue)] - Diff->Tax); }

	/** Game.act. Result text matches the Python return value. */
	Act Step(const Action& A, std::string& Result)
	{
		if (Over) return Act::GameOver;
		if (A.K != Kind::Rest)
		{
			if (A.Hue < 0 || A.Hue >= static_cast<int>(Prices.size()) || A.Count < 1) return Act::BadPick;
			const size_t H = static_cast<size_t>(A.Hue);
			if (A.K == Kind::Buy)
			{
				if (A.Count * Prices[H] > Purse || Held() + A.Count > Diff->Satchel) return Act::NoRoom;
				Purse -= A.Count * Prices[H]; Satchel[H] += A.Count;
			}
			else
			{
				if (A.Count > Satchel[H]) return Act::NotHeld;
				Purse += Sale(A.Hue, A.Count); Satchel[H] -= A.Count;
			}
			Score = Purse;
			Result = "purse " + std::to_string(Purse);
			return Act::Ok;
		}
		for (size_t I = 0; I < Prices.size(); ++I) Prices[I] = std::min(High, std::max(Low, Prices[I] + Moves[I]));
		++Day;
		if (Day > Diff->Days)
		{
			for (size_t I = 0; I < Satchel.size(); ++I) Purse += Sale(static_cast<int>(I), Satchel[I]);
			std::fill(Satchel.begin(), Satchel.end(), 0);
			Score = Purse; Over = true; Won = Purse >= Diff->Target;
			Result = "market closes, purse " + std::to_string(Purse);
			return Act::Ok;
		}
		NextMoves();
		Score = Purse;
		Result = "day " + std::to_string(Day);
		return Act::Ok;
	}

	/** Game.demo_action: sell what the rumor does not favour, buy the hue rumored to rise, else rest. */
	Action DemoAction() const
	{
		for (size_t J = 0; J < Satchel.size(); ++J)
			if (Satchel[J] && !(static_cast<int>(J) == RumorHue && RumorRise)) return { Kind::Sell, static_cast<int>(J), Satchel[J] };
		if (RumorRise && Day < Diff->Days)
		{
			const int Q = std::min(Purse / Prices[static_cast<size_t>(RumorHue)], Diff->Satchel - Held());
			if (Q > 0) return { Kind::Buy, RumorHue, Q };
		}
		return { Kind::Rest, 0, 0 };
	}
};

} } // namespace daedalus::glimmerloom
